import { readFileSync } from 'fs';
import pg from './node_modules/pg/lib/index.js';
const { Pool } = pg;
const rawUrl = String(process.env.DATABASE_URL||'');
const url = (() => { try { const u = new URL(rawUrl); ['sslmode','sslcert','sslkey','sslrootcert','sslpassword'].forEach(p=>u.searchParams.delete(p)); return u.toString(); } catch { return rawUrl; } })();
let ssl; try { ssl = { rejectUnauthorized: true, ca: readFileSync('./certs/rds-ca-bundle.pem') }; } catch { ssl = { rejectUnauthorized: false }; }
const pool = new Pool({ connectionString: url, ssl, max: 1 });
const c = await pool.connect();
let pass = true;

const { rows: mun } = await c.query('SELECT COUNT(*)::int AS n FROM municipalities');
const { rows: cid } = await c.query('SELECT COUNT(*)::int AS n FROM cid10');
const { rows: ciap } = await c.query('SELECT COUNT(*)::int AS n FROM ciap2');

console.log('municipalities=' + mun[0].n + (mun[0].n>=5570?' PASS':' FAIL'));
console.log('cid10=' + cid[0].n + (cid[0].n>=14000?' PASS':' FAIL'));
console.log('ciap2=' + ciap[0].n + (ciap[0].n>=650?' PASS':' FAIL'));
if (mun[0].n<5570||cid[0].n<14000||ciap[0].n<650) { pass=false; }

const { rows: j18 } = await c.query("SELECT code, description FROM cid10 WHERE code = 'J18'");
console.log('J18: ' + (j18[0] ? '"'+j18[0].description+'" PASS' : 'FAIL'));
if (!j18[0]) pass=false;

const { rows: r81 } = await c.query("SELECT description FROM ciap2 WHERE code = 'R81'");
console.log('CIAP2 R81: ' + (r81[0] ? '"'+r81[0].description+'" PASS' : 'FAIL'));
if (!r81[0]) pass=false;

const { rows: fk } = await c.query("SELECT 1 FROM information_schema.table_constraints WHERE table_name='app_units' AND constraint_name='fk_app_units_municipality_id'");
console.log('FK app_units: ' + (fk.length?'EXISTS PASS':'MISSING FAIL'));
if (!fk.length) pass=false;

const { rows: noFkPatients } = await c.query("SELECT 1 FROM information_schema.table_constraints WHERE table_name='app_patients' AND constraint_name LIKE 'fk_%municipality%'");
console.log('FK app_patients: ' + (noFkPatients.length?'EXISTS (unexpected!)':'NOT EXISTS (correct)'));
if (noFkPatients.length) { console.error('FAIL: FK on app_patients should not exist'); pass=false; }

const { rows: pCount } = await c.query('SELECT COUNT(*)::int AS n FROM app_patients');
const { rows: aCount } = await c.query('SELECT COUNT(*)::int AS n FROM app_audit_logs');
console.log('patients unchanged: ' + pCount[0].n + ' | audit_logs: ' + aCount[0].n);

const { rows: migs } = await c.query("SELECT COUNT(*)::int AS n FROM schema_migrations WHERE id IN ('021_create_municipalities','022_add_municipality_fk_to_units','023_create_cid10','024_create_ciap2')");
console.log('migrations 021-024: ' + migs[0].n + '/4 applied');
if (migs[0].n!==4) { pass=false; }

console.log(pass ? '\nGROUP-B-COMPLETE SMOKE PASS' : '\nGROUP-B-COMPLETE SMOKE FAIL');
c.release(); await pool.end();
